// Layered "worlds" for a 16:10 Mac display. Every world is a stack of planes
// with a depth (d). Parallax moves planes by d × cursor offset, so near planes
// move more than far ones — the cue your eyes use to read distance.
//
// SCENES is built from src/world-meta.json (names, colours, layer names and
// depths — generated by scripts/world-meta.mjs), so the page can render every
// label and card frame at once. Each world's heavy art (its SVG layers, or the
// GLSL of a GPU world) lives in its own chunk and is fetched by loadWorld():
// the first world right away, the others as they near the screen or at idle.

import { startTransition, useEffect, useState } from 'react'
import META from './world-meta.json'

const svgChunks = import.meta.glob(['./worlds/*.jsx', '!./worlds/kit.jsx'])
const glChunks = import.meta.glob('./gl/worlds/*.js')

// Layer names are shown as labels in the exploded view, so normalise them to
// sentence case.
const sentence = (t) => t.charAt(0).toUpperCase() + t.slice(1).toLowerCase()
const living = (w, isNew) => ({
  ...w,
  isNew,
  layers: w.layers.map((l) => ({ ...l, name: sentence(l.name) })),
})

// Ultra-real GPU worlds: one fragment shader renders every depth layer (see
// src/gl/runtime.js). The page's desktop clock is slotted in after layer
// `clockAfter`; `gl` keeps each layer's shader index for the exploded view.
function fromShader(w) {
  const layers = w.layers.map((l, i) => ({ ...l, gl: i }))
  const a = layers[w.clockAfter]?.depth ?? 0.3
  const b = layers[w.clockAfter + 1]?.depth ?? a + 0.2
  layers.splice(w.clockAfter + 1, 0, { name: 'Depth clock', depth: Number(((a + b) / 2).toFixed(2)), clock: true })
  return { ...w, shader: true, realistic: true, layers }
}

const gl = (file, isNew = false) => ({
  ...fromShader(META.gl[file]),
  isNew,
  chunk: `./gl/worlds/${file}.js`,
  build: (w) => ({ ...fromShader(w), isNew }),
})
const svg = (file, isNew = false) => ({
  ...living(META.svg[file], isNew),
  chunk: `./worlds/${file}.jsx`,
  build: (w) => living(w, isNew),
})

// GPU worlds, in page order. The newest carry a "New" badge.
const NEW_GL = new Set([
  'valleyofflowers', 'summit', 'turquoisebay', 'citylights', 'fjord', 'autumnlake', 'volcano', 'icefalls', 'sahara', 'stormlight', 'windowseat',
])
const REAL = [
  'valleyofflowers', 'flowervalley', 'summit', 'turquoisebay', 'citylights', 'aquarium', 'fjord', 'autumnlake', 'volcano',
  'ocean', 'icefalls', 'sahara', 'stormlight', 'windowseat', 'planet',
].map((f) => gl(f, NEW_GL.has(f)))
// The first six were rebuilt from the original classic worlds; the newest six
// keep their "New · alive" badge.
const CLASSIC = ['peaks', 'dunes', 'aurora', 'neon', 'abyss', 'nebula'].map((f) => svg(f))
const LIVING = ['blossom', 'islands', 'caravan', 'rainforest', 'lagoon', 'train'].map((f) => svg(f, true))

export const SCENES = [...REAL, ...CLASSIC, ...LIVING]

/* ---------- on-demand loading ---------- */

const loaded = new Map() // id -> full world (with layer `el`s, or `frag`)
const pending = new Map() // id -> Promise
const listeners = new Set()

// Dev guard: the metadata the page rendered with must match the real world.
const fingerprint = (w) =>
  JSON.stringify([
    w.id, w.name, w.tag, w.accent, w.accent2, w.ink, w.glow, !!w.light, w.clockColor, w.sky, w.clockAfter,
    w.layers.map((l) => [l.name, l.depth, !!l.sky, !!l.clock]),
  ])

/** Fetch a world's art (once). Resolves to the full scene object. */
export function loadWorld(scene) {
  // A world imported directly (preview/lab pages) already carries its art.
  if (!scene.chunk) return Promise.resolve(scene)
  if (loaded.has(scene.id)) return Promise.resolve(loaded.get(scene.id))
  if (!pending.has(scene.id)) {
    const chunks = scene.shader ? glChunks : svgChunks
    const p = chunks[scene.chunk]().then((m) => {
      const full = { ...scene, ...scene.build(m.default) }
      if (import.meta.env.DEV && fingerprint(full) !== fingerprint(scene)) {
        console.warn(`[worlds] src/world-meta.json is out of date for "${scene.id}" — run \`npm run worlds:meta\`.`)
      }
      loaded.set(scene.id, full)
      for (const fn of listeners) fn(scene.id)
      // Mounting a world is a one-off hitch; tell the animation budget to
      // ignore it rather than mistake it for a slow machine.
      dispatchEvent(new Event('world-mount'))
      return full
    })
    pending.set(scene.id, p)
  }
  return pending.get(scene.id)
}

/**
 * The full world for `scene` once its art has loaded (undefined until then).
 * With `fetch` false it only listens (SceneView fetches once the world nears
 * the screen). The swap-in renders as a transition, so a big world mounting
 * doesn't block scrolling.
 */
export function useWorld(scene, fetch = true) {
  const [full, setFull] = useState(() => loaded.get(scene.id))
  useEffect(() => {
    if (!scene.chunk) return
    const fn = (id) => {
      if (id === scene.id) startTransition(() => setFull(loaded.get(id)))
    }
    listeners.add(fn)
    // It may have arrived between this component's render and now.
    if (loaded.has(scene.id)) fn(scene.id)
    else if (fetch) loadWorld(scene)
    return () => {
      listeners.delete(fn)
    }
  }, [scene, fetch])
  if (!scene.chunk) return scene
  return loaded.get(scene.id) ?? (full?.id === scene.id ? full : undefined)
}

// The default (hero) world starts loading at once; prefetchWorlds() then pulls
// in the rest one at a time whenever the browser is idle.
loadWorld(SCENES[0])
export function prefetchWorlds() {
  const idle = (fn) => (window.requestIdleCallback ? requestIdleCallback(fn, { timeout: 2500 }) : setTimeout(fn, 300))
  let i = 0
  const next = () => {
    while (i < SCENES.length && loaded.has(SCENES[i].id)) i++
    if (i >= SCENES.length) return
    loadWorld(SCENES[i++]).finally(() => idle(next))
  }
  idle(next)
}
